namespace {
using namespace fathom;using namespace fathom::storage;using V=json::Value;using A=V::Array;using O=V::Object;
const V& f(const V& v,const std::string& k){auto p=v.find(k);if(!p)throw std::runtime_error("Missing fixture "+k);return *p;}
V read(const std::filesystem::path& p){return json::parse(content::readBounded(p,32*1024*1024));}
void save(const std::filesystem::path& p,const V& v){std::ofstream out(p);out<<canonical(v)<<'\n';if(!out)throw std::runtime_error("Cannot retain result");}
void directory(const std::filesystem::path& p){if(::mkdir(p.c_str(),0700)!=0)throw std::runtime_error("Fresh private directory required: "+p.string());}
V hashes(const std::filesystem::path& db){O out;for(auto suffix:{"","-wal","-shm","-journal"}){auto p=std::filesystem::path(db.string()+suffix);if(!std::filesystem::exists(p)){out.emplace(suffix,nullptr);continue;}out.emplace(suffix,O{{"bytes",V::fromInteger(static_cast<std::int64_t>(std::filesystem::file_size(p)))},{"sha256",content::sha256(content::readBounded(p,64*1024*1024))}});}return out;}
void clone(const std::filesystem::path& source,const std::filesystem::path& directoryPath){directory(directoryPath);for(auto suffix:{"","-wal","-shm","-journal"}){auto from=std::filesystem::path(source.string()+suffix);if(!std::filesystem::exists(from))continue;auto to=directoryPath/(std::string("profile.sqlite")+suffix);std::filesystem::copy_file(from,to);if(chmod(to.c_str(),0600)!=0)throw std::runtime_error("Fixture mode failed");}}
void sql(const std::filesystem::path& p,const std::string& statement){sqlite3* db=nullptr;if(sqlite3_open_v2(p.c_str(),&db,SQLITE_OPEN_READWRITE,nullptr)!=SQLITE_OK)throw std::runtime_error("Cannot mutate isolated fixture");char* error=nullptr;auto rc=sqlite3_exec(db,statement.c_str(),nullptr,nullptr,&error);std::string why=error?error:"";sqlite3_free(error);sqlite3_close(db);if(rc!=SQLITE_OK)throw std::runtime_error("Fixture SQL failed: "+why);}
V replyValue(const Reply& r){return O{{"status",statusName(r.status)},{"operation",r.operation},{"code",r.code},{"message",r.message},{"data",r.data}};}
V lookup(const V& cases){A results;for(auto& c:cases.array()){O row{{"id",f(c,"id")}};try{Reply s;s.status=Status::Confirmed;s.code="CONFIRMED";s.data=f(c,"snapshot");row.emplace("result",historicalContentContinuity(s,f(c,"available")));}catch(const std::exception& e){row.emplace("error",e.what());}results.emplace_back(row);}return results;}
V guard(const std::filesystem::path& root){
    A results;for(bool stopped:{false,true}){CompatibilityOptions o;o.original=root/"never-open-profile/profile.sqlite";o.stage=root/"never-create-stage";o.operation=stopped?"unresolved-stopped":"active-refusal";o.applicationVersion="synthetic-refusal-only";o.applicationBuildSha256=std::string(64,'a');o.stopped=stopped;o.unresolvedWrites=true;auto r=inspectCompatibility(o);bool passed=r.status==Status::Busy&&r.code=="QUIESCENCE_REQUIRED"&&f(r.data,"return_transport")==V(stopped?"stopped":"unchanged; explicit stop required")&&!std::filesystem::exists(o.stage)&&!std::filesystem::exists(o.original.parent_path());results.emplace_back(O{{"stopped_input",stopped},{"reply",replyValue(r)},{"passed",passed}});}int passed=0;for(auto& v:results)if(f(v,"passed")==V(true))++passed;return O{{"cases",results},{"passed",V::fromInteger(passed)},{"total",V::fromInteger(2)}};
}
V native(const std::filesystem::path& root,const std::string& buildIdentity,bool corruptionOnly=false){
    if(!root.is_absolute()||root.filename().string().find("-evidence")==std::string::npos)throw std::runtime_error("Explicit synthetic evidence root required");
    auto inputs=root/"fixtures/raw-v1/profile.sqlite",output=root/(corruptionOnly?"test-data/native02":"test-data/native01");directory(output);A cases;
    auto run=[&](const std::string& name,auto prepare,auto assess){if(corruptionOnly&&name!="corrupt-sqlite-header")return;auto d=output/name;directory(d);clone(inputs,d/"profile");CompatibilityOptions o;o.original=d/"profile/profile.sqlite";o.stage=d/"stage";o.operation=name;o.applicationVersion="0.1.0-current-compatibility-component";o.applicationBuildSha256=buildIdentity;o.stopped=true;o.unresolvedWrites=false;prepare(o,d);auto before=hashes(o.original);auto begin=std::chrono::steady_clock::now();auto r=inspectCompatibility(o);auto after=hashes(o.original);auto elapsed=std::chrono::duration_cast<std::chrono::microseconds>(std::chrono::steady_clock::now()-begin).count();V evidence=O{{"name",name},{"original_before",before},{"original_after",after},{"reply",replyValue(r)},{"elapsed_microseconds",V::fromInteger(elapsed)}};bool okay=assess(r,d,before,after);evidence.object().emplace("passed",okay);save(d/"result.json",evidence);cases.push_back(evidence);};
    auto none=[](auto&,auto&){};auto unchanged=[](const auto&,const auto&,const V& a,const V& b){return a==b;};
    run("compatible-schema1",none,[&](const Reply& r,const auto&,const V& a,const V& b){return r.status==Status::Confirmed&&r.code=="COMPATIBLE_NO_DATA_MIGRATION"&&a==b&&f(r.data,"original_preserved")==V(true)&&f(r.data,"transformation_performed")==V(false);});
    run("unknown-target",[](auto& o,const auto&){o.targetDataSchema=2;},[&](const Reply& r,const auto&,const V& a,const V& b){return r.status==Status::Unsupported&&r.code=="NO_MIGRATION_HANDLER"&&a==b;});
    run("active-transport",[](auto& o,const auto&){o.stopped=false;},[&](const Reply& r,const auto&,const V& a,const V& b){return r.status==Status::Busy&&r.code=="QUIESCENCE_REQUIRED"&&f(r.data,"return_transport")==V("unchanged; explicit stop required")&&a==b;});
    run("unresolved-caller",[](auto& o,const auto&){o.unresolvedWrites=true;},[&](const Reply& r,const auto&,const V& a,const V& b){return r.status==Status::Busy&&a==b;});
    run("unknown-schema2",[](auto& o,const auto&){sql(o.original,"PRAGMA user_version=2;");},[&](const Reply& r,const auto&,const V& a,const V& b){return r.status==Status::Unsupported&&r.code=="UNSUPPORTED_DATA_SCHEMA"&&a==b&&f(r.data,"original_preserved")==V(true);});
    run("wrong-application",[](auto& o,const auto&){sql(o.original,"PRAGMA application_id=0;");},[&](const Reply& r,const auto&,const V& a,const V& b){return r.status!=Status::Confirmed&&r.code=="WRONG_PROFILE_FORMAT"&&a==b;});
    run("changed-schema-trigger",[](auto& o,const auto&){sql(o.original,"DROP TRIGGER final_no_update;");},[&](const Reply& r,const auto&,const V& a,const V& b){return r.status!=Status::Confirmed&&a==b&&f(r.data,"original_preserved")==V(true);});
    run("corrupt-sqlite-header",[](auto& o,const auto& d){sql(o.original,"PRAGMA wal_checkpoint(TRUNCATE);");if(std::filesystem::exists(o.original.string()+"-wal")||std::filesystem::exists(o.original.string()+"-shm"))throw std::runtime_error("Corruption fixture still has WAL/SHM");auto intact=content::readBounded(o.original,64*1024*1024);if(intact.substr(0,16)!=std::string("SQLite format 3\0",16))throw std::runtime_error("Intact fixture header absent");save(d/"before-corruption.json",hashes(o.original));std::fstream file(o.original,std::ios::in|std::ios::out|std::ios::binary);file.put('X');if(!file)throw std::runtime_error("Fixture corruption failed");},[&](const Reply& r,const auto&,const V& a,const V& b){return r.status!=Status::Confirmed&&a==b&&f(r.data,"original_preserved")==V(true);});
    run("missing-shm",[](auto& o,const auto&){if(!std::filesystem::remove(o.original.string()+"-shm"))throw std::runtime_error("WAL fixture SHM absent");},[&](const Reply& r,const auto&,const V& a,const V& b){return r.status!=Status::Confirmed&&r.code=="RECOVERY_REQUIRED"&&a==b;});
    run("journal-refusal",[](auto& o,const auto&){std::ofstream p(o.original.string()+"-journal");p<<"synthetic unsupported journal";p.close();chmod((o.original.string()+"-journal").c_str(),0600);},[&](const Reply& r,const auto&,const V& a,const V& b){return r.code=="RECOVERY_REQUIRED"&&a==b;});
    run("stage-already-exists",[](auto& o,const auto&){directory(o.stage);},[&](const Reply& r,const auto&,const V& a,const V& b){return r.code=="STAGE_EXISTS_OR_UNAVAILABLE"&&a==b;});
    run("source-stage-alias",[](auto& o,const auto&){o.stage=o.original.parent_path()/"forbidden-stage";},[&](const Reply& r,const auto&,const V& a,const V& b){return r.status!=Status::Confirmed&&a==b;});
    run("copy-capacity",[](auto& o,const auto&){o.maxImageBytes=1;},[&](const Reply& r,const auto&,const V& a,const V& b){return r.code=="COPY_CAPACITY"&&a==b;});
    run("invalid-huge-deadline",[](auto& o,const auto&){o.copyDeadline=std::chrono::milliseconds::max();},[&](const Reply& r,const auto& d,const V& a,const V& b){return r.status!=Status::Confirmed&&a==b&&!std::filesystem::exists(d/"stage");});
    run("stage-copy-failure",[](auto& o,const auto& d){o.diagnosticHook=[d](const auto& phase){if(phase=="raw-image-verified"){std::filesystem::remove(d/"stage/candidate");std::ofstream file(d/"stage/candidate");file<<"synthetic obstruction";}};},[&](const Reply& r,const auto& d,const V& a,const V& b){return r.status!=Status::Confirmed&&a==b&&hashes(d/"stage/original-image/profile.sqlite")==a;});
    run("identical-byte-original-replacement",[](auto& o,const auto& d){o.diagnosticHook=[d](const auto& phase){if(phase=="raw-image-verified"){auto from=d/"profile/profile.sqlite",copy=d/"replacement";std::filesystem::copy_file(from,copy);chmod(copy.c_str(),0600);std::filesystem::rename(copy,from);}};},[&](const Reply& r,const auto& d,const V& a,const V& b){return r.code=="PROFILE_CHANGED"&&a==b&&f(r.data,"original_preserved")==V(false)&&hashes(d/"stage/original-image/profile.sqlite")==a;});
    run("durable-unfinished-owner",[](auto& o,const auto& d){StoreOptions options;options.path=o.original;ProfileStore store(options);auto s=store.snapshot("fixture-before").get();auto authority=f(s.data,"authoritative");auto rows=f(authority,"identity").array();V context;for(auto& row:rows)if(row.array()[1]==V("Attempt")){auto bytes=f(row.array()[4],"blob_hex").string();std::string decoded;for(std::size_t i=0;i<bytes.size();i+=2)decoded.push_back(static_cast<char>(std::stoi(bytes.substr(i,2),nullptr,16)));context=parseCanonical(decoded);break;}auto allocation=store.allocate("fixture-unfinished","Attempt",context,"2026-09-07T20:00:00Z").get();if(allocation.status!=Status::Confirmed)throw std::runtime_error("Cannot allocate synthetic unfinished owner");save(d/"fixture-allocation.json",replyValue(allocation));},[&](const Reply& r,const auto&,const V& a,const V& b){return r.status==Status::Busy&&r.code=="RECOVERY_REQUIRED"&&a==b;});
    run("repeated-compatible-inspection",[](auto& o,const auto& d){auto first=inspectCompatibility(o);save(d/"first-result.json",replyValue(first));if(first.status!=Status::Confirmed)throw std::runtime_error("First repeated inspection failed");o.stage=d/"second-stage";o.operation="repeated-compatible-inspection-second";},[&](const Reply& r,const auto& d,const V& a,const V& b){auto first=read(d/"first-result.json");return r.status==Status::Confirmed&&a==b&&f(f(first,"data"),"snapshot")==f(r.data,"snapshot");});
    run("missing-original",[](auto& o,const auto&){for(auto suffix:{"","-wal","-shm"})std::filesystem::remove(o.original.string()+suffix);},[&](const Reply& r,const auto& d,const V& a,const V& b){return r.status!=Status::Confirmed&&a==b&&!std::filesystem::exists(d/"stage");});
    run("symlink-original",[](auto& o,const auto& d){auto actual=d/"profile/actual.sqlite";std::filesystem::rename(o.original,actual);std::filesystem::create_symlink(actual.filename(),o.original);},[&](const Reply& r,const auto& d,const V& a,const V& b){return r.status!=Status::Confirmed&&a==b&&!std::filesystem::exists(d/"stage");});
    run("unsafe-original-permissions",[](auto& o,const auto&){if(chmod(o.original.c_str(),0644)!=0)throw std::runtime_error("Cannot prepare unsafe own file");},[&](const Reply& r,const auto& d,const V& a,const V& b){return r.status!=Status::Confirmed&&a==b&&!std::filesystem::exists(d/"stage");});
    std::unique_ptr<ProfileLease> held;
    run("held-original-lease",[&](auto& o,const auto&){held=std::make_unique<ProfileLease>(o.original,false);},[&](const Reply& r,const auto& d,const V& a,const V& b){return r.status!=Status::Confirmed&&a==b&&!std::filesystem::exists(d/"stage");});held.reset();
    (void)unchanged;
    int passed=0;for(auto& c:cases)if(f(c,"passed")==V(true))++passed;return O{{"cases",cases},{"passed",V::fromInteger(passed)},{"total",V::fromInteger(static_cast<std::int64_t>(cases.size()))}};
}
}
int main(int argc,char** argv){try{if(argc!=3)throw std::runtime_error("Usage --lookup cases.json OR --native synthetic-evidence-root");V result;if(std::string(argv[1])=="--lookup")result=lookup(read(argv[2]));else if(std::string(argv[1])=="--native")result=native(argv[2],content::sha256(content::readBounded(std::filesystem::canonical(argv[0]),64*1024*1024)));else if(std::string(argv[1])=="--native-corrupt")result=native(argv[2],content::sha256(content::readBounded(std::filesystem::canonical(argv[0]),64*1024*1024)),true);else if(std::string(argv[1])=="--guard")result=guard(argv[2]);else throw std::runtime_error("Unknown explicit mode");std::cout<<canonical(result)<<'\n';return result.find("total")&&f(result,"total")!=f(result,"passed")?1:0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 2;}}
